/**
 * D764 (#2089) — the rail's model matrix, read.
 *
 * `railMatrix.json` is generated by `scripts/build-rail-matrix.mjs` from the
 * owner's canvas and never edited here: one row per page, its kind of work,
 * its router task and its models, default first; and (PR 3) one row per
 * option a profile's list registers. This file answers `resolveRail(page)`,
 * `resolveRailOption(page, option)` and `railOptionsOn(page)`, and the rules a
 * pick is checked by.
 *
 * Pure: no binding. `routes/ai.ts` reads it, and `aiRouter.run` resolves a
 * rail run's models through `resolveRailChain` (PR 3), given the member's
 * stored picks and the owner's switches.
 */
import matrix from './railMatrix.json';
import * as catalogue from './catalogue';

export type RailModel = { id: string; role: string; line: string };
export type RailRow = { pageKey: string; kind: string; routeTask: string; models: RailModel[] };
export type RailOptionRow = RailRow & { optionKey: string; optionLabel: string; handler: string };

const ROWS: readonly RailRow[] = matrix.rows;
const BY_KEY = new Map(ROWS.map((r) => [r.pageKey.toLowerCase(), r]));
const OPTIONS: readonly RailOptionRow[] = matrix.options;
const OPTIONS_BY_PAGE = new Map<string, RailOptionRow[]>();
for (const o of OPTIONS) {
  const k = o.pageKey.toLowerCase();
  OPTIONS_BY_PAGE.set(k, [...(OPTIONS_BY_PAGE.get(k) ?? []), o]);
}

/** Every page row, in the canvas's order. */
export function railRows(): readonly RailRow[] {
  return ROWS;
}

/**
 * The page's row, matched without regard to case, so the stored section
 * (`ai_rail_preferences.section`, the page key lower-cased, D720 §6) finds it
 * too. Null for a page the matrix has no row for.
 */
export function resolveRail(page: string | null | undefined): RailRow | null {
  if (typeof page !== 'string') return null;
  return BY_KEY.get(page.trim().toLowerCase()) ?? null;
}

/** Every registered option row, in the profiles' order. */
export function railOptionRows(): readonly RailOptionRow[] {
  return OPTIONS;
}

/** The options a page offers that run a model, in its list's order. */
export function railOptionsOn(page: string | null | undefined): readonly RailOptionRow[] {
  return typeof page === 'string' ? OPTIONS_BY_PAGE.get(page.trim().toLowerCase()) ?? [] : [];
}

/** One option's row on a page, or null when the page registers no such option. */
export function resolveRailOption(page: string | null | undefined, option: string | null | undefined): RailOptionRow | null {
  if (typeof option !== 'string') return null;
  return railOptionsOn(page).find((o) => o.optionKey === option) ?? null;
}

/** The preference section a page's picks and mode are stored under. */
export function railSectionOf(row: RailRow): string {
  return row.pageKey.toLowerCase();
}

/** The breadcrumb the rail draws: the page key's parts. */
export function railCrumbs(row: RailRow): string[] {
  return row.pageKey.split(' · ');
}

/** True when the row offers this model, the only picks a page accepts. */
export function rowOffers(row: RailRow, model: string): boolean {
  return row.models.some((m) => m.id === model);
}

// ---------------------------------------------------------------------------
// D764 PR 3 — a run with rail context resolves its models from the row.
// ---------------------------------------------------------------------------

/** What a run asks of a model: text in and out, and whether it sends images. */
export type RailNeed = { vision: boolean };

/**
 * A model that can do a text run (and read its images when it sends some),
 * as D760's catalogue describes it, and that the catalogue offers today. The
 * row's embedding, rerank, translation and speech models never answer a chat
 * run; `compatibleModels` keeps them out.
 */
export function canRun(id: string, need: RailNeed, env: catalogue.CatalogueSwitches): boolean {
  const m = catalogue.modelById(id);
  if (!m || m.kind !== 'Text Generation' || !catalogue.isOffered(m, env)) return false;
  return !need.vision || m.capabilities.includes('Vision');
}

/** The row's models a run may use, in the row's order. */
export function compatibleModels(row: RailRow, need: RailNeed, env: catalogue.CatalogueSwitches): string[] {
  return row.models.map((m) => m.id).filter((id) => canRun(id, need, env));
}

export type RailChain =
  | { ok: true; primary: string; chain: string[]; source: 'caller' | 'pick' | 'default' }
  | { ok: false; refusal: 'model_not_offered'; model: string };

/**
 * D720 §5's run rule. The primary is the caller's model when it can do the
 * work (else `model_not_offered`), then the member's stored pick (the
 * option's, then the page's) when the row still offers it, then the row's
 * first model a free plan runs (the paid-only demotion, unless the owner set
 * AI_PAID_MODELS = "on"). The chain is the row's other models of the same
 * shape; a paid-only one leaves the chain while the demotion holds. Null when
 * the row has no model for this run: the task's own route answers it.
 */
export function resolveRailChain(
  row: RailRow,
  need: RailNeed,
  env: catalogue.CatalogueSwitches,
  picks: { caller?: string | null; option?: string | null; page?: string | null },
): RailChain | null {
  const fits = compatibleModels(row, need, env);
  if (picks.caller && !canRun(picks.caller, need, env)) return { ok: false, refusal: 'model_not_offered', model: picks.caller };
  if (!fits.length && !picks.caller) return null;
  const demoted = catalogue.defaultDemoted(env);
  const paid = (id: string) => catalogue.modelById(id)?.paid_only === true;
  const stored = [picks.option, picks.page].find((id) => id && fits.includes(id)) ?? null;
  const fallback = (demoted ? fits.find((id) => !paid(id)) : null) ?? fits[0];
  const primary = picks.caller ?? stored ?? fallback;
  const source = picks.caller ? 'caller' : stored ? 'pick' : 'default';
  const chain = fits.filter((id) => id !== primary && !(demoted && paid(id)));
  return { ok: true, primary, chain, source };
}
